use vstd::prelude::*;

verus! {

    // Build and return an f64‐vector of length exactly n.
    // No requirements on the contents (we just push 0.0 each time).
    fn empty(n: u8) -> (result: Vec<f64>)
        ensures
            // Post‐condition: the returned vector has exactly length n
            result.len() == n as nat,
    {
        // Start with an empty vector
        let mut v: Vec<f64> = Vec::new();

        // Keep pushing until we reach length n
        while v.len() < n as nat
            invariant
                // At all times, len(v) stays ≤ n
                v.len() <= n as nat,
            decreases
                // The remaining difference (n – len(v)) decreases each iteration
                (n as nat) - v.len(),
        {
            // Push a dummy value
            v.push(0.0);
        }

        // Return the fully‐sized vector
        result = v;
    }
}

